    def import_fastpass_package(self, package_file_path):
        """
        Add a metadata package file.

        This interface helps to import a metadata Fast Pass package in Network Operations Master.
        The method returns 40x in the case of Authorization failure.

        :param str package_file_path: Path to package file.
        """
