    def wait_for_operation_status(self, operation_id, timeout, retry_interval=1):
        """
        Check operation status until it is finished or timeout is exceeded.

        :param string operation_id: Id of operation.
        :param Union[int,str] timeout: Time to wait for the response of the current operation.
        :param Union[int,str] retry_interval: Time to wait between operation status checks.

        :return list[dict]: Every ``dict`` contains ``operation_id``, ``status`` and ``timestamp`` attributes.
            Example the same as for :meth:`get_operation_status`.
        """
        return self.connection.wait_for_operation_status(operation_id, time_to_seconds(timeout),
                                                         time_to_seconds(retry_interval))

    def interrupt_operation(self, operation_id):
        """
        Requests the interruption of the operation with given operation ID.

        This will interrupt the operation with the given operation ID and its suboperations if applicable.
        All queuing suboperations of the given operation ID are interrupted except for a queuing ``ne-swm-operation``.
        In addition, all ongoing suboperations that are cancellable (``ne3s-swm-download``, ``ne3s-swm-provision``
        and ``ne3s-swm-atomic-provision``) are interrupted.

        :param string operation_id: Id of operation to interrupt.

        :return list[str]: Returns a list of interrupted operations.
        """
        return self.connection.interrupt_operation(operation_id).to_dict()

