    def import_cnf_plan(self, plan_name, plan_type, cnf_data,
                        override=True, description=None, secret_paths=None):
        """
        Import or update configuration with given managed object, values and secrets.

        :param str plan_name: The name of the configuration.
        :param bool override: If set to ``True``, the existing plan will be updated.
        :param str plan_type: The type of the configuration, used to differentiate plans for different use cases,
            e.g.: ``CNF_CREATE``, ``CNF_ROLLBACK``, ``CNF_UPGRADE``, ``CNF_DELETE``
        :param dict cnf_data: The content of the configuration,
            e.g.::

                {
                    "managedObjects": [
                      {
                        "moId": "CNF-1",
                        "moClass": {
                          "id": "com.nokia.vran.lcm:CNF",
                          "version": "0.1"
                        },
                        "planOperation": "UPDATE",
                        "parameters": {
                          "cnfSwId": "vDU-0.300.260",
                          "deploymentProfile": [
                            {
                              "chart": "cnf-lcm-operations-0.1.62.tgz",
                              "order": 0,
                              "releaseName": "test-hook-one",
                              "values": ""
                            }
                          ],
                          "VIM": "VIM-1"
                        }
                      }
                    ]
                }

        :param str description: Description of the configuration content and/or purpose.
        :param str secret_paths: Paths to values that user want to store in vault as sensitive data.

        :return dict: Contains ``code`` and ``message`` keys.
        """
        return self.connection.import_cnf_plan(
            plan_name, plan_type, cnf_data, to_boolean(override), description, secret_paths).to_dict()

