    def import_ssd_raml(self, plan_content, **kwargs):
        """
        Import planned Security Sensitive Data (SSD) of the network elements defined in the given plan to NOM.

        :param str plan_content: Plan content in RAML2.1 format.

        :\\**kwargs:
            - **overwrite** (bool) - Allows to add new data or update already planned SSD for network element. \
                To overwrite an existing SSD, the user has to set this parameter to ``True``. \
                By default, importing planned SSD for the NE that already exists will not allow to update it. \
                This is to prevent accidental updates of planned SSD content.
            - **complete_bts_overwrite** (bool) - Allows to completely replace already planned SSD for network element. \
                To completely replace an existing SSD, the user has to set this parameter to ``True``. \
                By default, importing planned SSD for the NE that already exists will not allow to replace it. \
                This is to prevent accidental replace of planned SSD content.

        :return list[dict]: Every ``dict`` contains ``operation_id``, ``timestamp``, ``type``, ``message``,
            ``details`` and ``object_dn`` keys.
        """
        return self.connection.import_ssd_raml(plan_content=plan_content, **kwargs).to_dict()

